/* Set up a jump arc in p[5..7] for distance a and height b under the gravity in p[4]. */
void trooper_set_knockback(float *p, float a, float b)
{
    float root = vec_length((b + b) * p[4]);
    float x = (root + root) / p[4];
    p[7] = root;
    p[6] = (a + a) / x;
    p[5] = (a + a) / (x * x);
}
